import type { CalloutVariant } from '../data/docs';
import Inline from './Inline';
import { Icon } from './pixel';

const ICONS = {
  note: 'info',
  warning: 'warning',
  danger: 'danger',
} as const;

const VARIANT_NAMES: Record<CalloutVariant, string> = {
  note: 'Note',
  warning: 'Warning',
